ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'output/pdf/rustemu8086-ui-ux-audit-2026-11-16.pdf'
SNAP = ROOT / 'target/ui-snapshots'
for name, file in [('Regular','Arial.ttf'),('Bold','Arial Bold.ttf'),('Italic','Arial Italic.ttf')]:
    pdfmetrics.registerFont(TTFont(name, '/System/Library/Fonts/Supplemental/' + file))
pdfmetrics.registerFontFamily('Regular', normal='Regular', bold='Bold', italic='Italic', boldItalic='Bold')
W,H=595.28,841.89
M=43
CW=W-2*M
c=canvas.Canvas(str(OUT), pagesize=(W,H))
c.setTitle('RustEmu8086 Аудит UI UX и демонстрация возможностей')
c.setAuthor('RustEmu8086')
styles={
 'body':ParagraphStyle('body',fontName='Regular',fontSize=10.2,leading=14.2,textColor=HexColor('#202732'),spaceAfter=8),
 'small':ParagraphStyle('small',fontName='Regular',fontSize=8.2,leading=11,textColor=HexColor('#596372')),
 'h2':ParagraphStyle('h2',fontName='Bold',fontSize=13,leading=17,textColor=black),
 'cell':ParagraphStyle('cell',fontName='Regular',fontSize=8.5,leading=11.4),
 'head':ParagraphStyle('head',fontName='Bold',fontSize=8.5,leading=11.4,textColor=black),
}
y=0
page=0
def para(text, style='body', x=M, width=CW, gap=7):
    global y
    p=Paragraph(text,styles[style]); _,h=p.wrap(width,700)
    p.drawOn(c,x,y-h); y-=h+gap
def start(title, subtitle):
    global page,y
    if page: c.showPage()
    page+=1; y=H-M
    c.setFont('Regular',8);c.setFillColor(HexColor('#596372'))
    c.drawString(M,y,'RUSTEMU8086  /  АУДИТ ПРОДУКТА  /  16 НОЯБРЯ 2026')
    y-=32;c.setFillColor(black);c.setFont('Bold',21);c.drawString(M,y,title);y-=25
    para(subtitle,'small',gap=17)
    c.setFont('Regular',8);c.setFillColor(HexColor('#596372'))
    c.drawString(M,25,'Локальный проект 181b02b • UI-снимки из тестового корпуса')
    c.drawRightString(W-M,25,f'{page:02d} / 11')
def sub(t):
    global y
    y-=3;para(t,'h2',gap=8)
def image(name, caption, crop=None, maxheight=340, marks=()):
    global y
    im=Image.open(SNAP/name).convert('RGB')
    if crop: im=im.crop(crop)
    iw,ih=im.size; scale=min(CW/iw,maxheight/ih); dw,dh=iw*scale,ih*scale
    x=M+(CW-dw)/2
    c.drawImage(ImageReader(im),x,y-dh,width=dw,height=dh)
    for n,px,py in marks:
        xx=x+px*dw; yy=y-py*dh
        c.setFillColor(HexColor('#1264ab'));c.setStrokeColor(white);c.setLineWidth(1)
        c.circle(xx,yy,9,fill=1,stroke=1);c.setFillColor(white);c.setFont('Bold',9)
        c.drawCentredString(xx,yy-3,str(n))
    y-=dh+7;para(caption,'small',gap=12)
def table(headers, rows, widths):
    global y
    data=[[Paragraph(escape(v),styles['head']) for v in headers]]+[[Paragraph(v,styles['cell']) for v in row] for row in rows]
    t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),HexColor('#e9edf2')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,0),0.7,HexColor('#aab5c2')),('LINEBELOW',(0,1),(-1,-1),0.35,HexColor('#d9e0e7'))]))
    _,hh=t.wrap(CW,700);t.drawOn(c,M,y-hh);y-=hh+12
def note(text):
    global y
    p=Paragraph(text,styles['body']);_,hh=p.wrap(CW-22,700)
    c.setFillColor(HexColor('#eef4f9'));c.roundRect(M,y-hh-18,CW,hh+18,5,fill=1,stroke=0)
    p.drawOn(c,M+11,y-hh-9);y-=hh+29
def check():
    if y<48: raise RuntimeError(f'Page {page} overflows: {y}')

